-- ═══════════ PATCH 04 — ORG CHART ═══════════
--
-- `org_chart_nodes` came from the "Org Chart Info" sheet, which covers
-- leadership only and carries no tile level, department slug, photo, email or
-- project-manager flag. The org chart page needs all of those, so pointing it
-- at the table as it stood would have dropped ten people and flattened the
-- hierarchy.
--
-- This widens the table to hold everything the chart draws, then reloads it
-- from the richer hand-maintained source. After this the org chart reads from
-- the database like every other page, and PMs can edit it.
--
-- Run after patch-03. Safe to re-run.

begin;

-- ── the fields the chart needs ────────────────────────────────────────────
alter table public.org_chart_nodes
  add column if not exists node_key      text,      -- stable id used by the chart
  add column if not exists reports_to_key text,     -- parent's node_key
  add column if not exists dept_slug     text,      -- executive|records|enrollment|dean|digital
  add column if not exists level         integer,   -- 1 VP … 5 staff
  add column if not exists email         text,
  add column if not exists photo_url     text,
  add column if not exists is_pm         boolean not null default false,
  add column if not exists pm_position   text,      -- left|right, for PM tiles
  add column if not exists responsibilities text[],
  add column if not exists kpis          text[];

create unique index if not exists org_chart_nodes_key_idx
  on public.org_chart_nodes (node_key);

-- ── keep the sheet's narrative text, keyed by name ────────────────────────
create temporary table _sheet_text on commit drop as
  select lower(trim(name)) as name_key, stewardships, key_kpis,
         key_responsibilities, direct_reports
    from public.org_chart_nodes
   where stewardships is not null or key_kpis is not null;

delete from public.org_chart_nodes;

insert into public.org_chart_nodes (sort_order, node_key, name, role, employee_status, reports_to, reports_to_key, dept_slug, department, level, email, photo_url, link, is_pm, pm_position, responsibilities, kpis) values
