-- parent's display name, derived from the key so the two cannot disagree
update public.org_chart_nodes c
   set reports_to = p.name
  from public.org_chart_nodes p
 where c.reports_to_key = p.node_key;

-- long department name, for the pages that show it
update public.org_chart_nodes set department = case dept_slug
  when 'executive'  then 'VP - Student Services'
  when 'records'    then 'Student Records, Registration, and Support'
  when 'enrollment' then 'Enrollment & Retention'
  when 'dean'       then 'Dean of Students'
  when 'digital'    then 'Digital Operations'
  else department end;

-- put the sheet's stewardship / KPI wording back where the names match
update public.org_chart_nodes c
   set stewardships         = coalesce(c.stewardships, s.stewardships),
       key_kpis             = coalesce(c.key_kpis, s.key_kpis),
       key_responsibilities = coalesce(c.key_responsibilities, s.key_responsibilities),
       direct_reports       = coalesce(c.direct_reports, s.direct_reports)
  from _sheet_text s
 where lower(trim(c.name)) = s.name_key;

-- ── what the org chart page reads ─────────────────────────────────────────
create or replace view public.v_hub_org_chart as
  select node_key as id, name, role as title, dept_slug as dept, level,
         employee_status as status, reports_to_key as "reportsTo",
         coalesce(responsibilities, '{}') as responsibilities,
         coalesce(kpis, '{}') as kpis,
         email, photo_url as "photoUrl", link as "roleInventoryUrl",
         case when is_pm then 'pm' end as role_kind,
         pm_position as "pmPosition",
         stewardships, key_kpis, key_responsibilities, direct_reports
    from public.org_chart_nodes
   order by level, sort_order;

alter view public.v_hub_org_chart set (security_invoker = on);
grant select on public.v_hub_org_chart to anon, authenticated;

commit;
